<template><section class="business-page"><header class="page-header"><div><h1>组合商品</h1><p>选择多个已有普通 SKU，生成新的组合 SPU / SKU，并保存组成数量。</p></div><el-button v-if="canManage" type="primary" @click="visible=true">新建组合 SKU</el-button></header><el-table :data="bundles" border><el-table-column prop="spu_code" label="组合 SPU"/><el-table-column prop="product_name" label="组合商品名称"/><el-table-column label="组合 SKU"><template #default="{row}">{{skus.filter(x=>x.spu===row.id).map(x=>x.sku_code).join('、')||'-'}}</template></el-table-column></el-table><el-dialog v-model="visible" title="由现有 SKU 创建组合 SKU" width="720px"><el-form label-position="top"><el-form-item label="组合商品名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="末级分类"><el-select v-model="form.category" filterable><el-option v-for="x in leaves" :key="x.id" :label="`${x.code} ${x.name}`" :value="x.id"/></el-select></el-form-item><el-form-item label="季节"><el-select v-model="form.season"><el-option v-for="x in options.seasons" :key="x.code" :label="x.name" :value="x.code"/></el-select></el-form-item><el-form-item label="组合颜色"><el-select v-model="form.color"><el-option v-for="x in colors" :key="x.code" :label="`${x.name} (${x.code})`" :value="x.code"/></el-select></el-form-item><el-form-item label="组成 SKU"><div class="components"><div v-for="(x,i) in form.components" :key="i"><el-select v-model="x.sku" filterable><el-option v-for="s in normalSkus" :key="s.id" :label="s.sku_code" :value="s.id"/></el-select><el-input-number v-model="x.quantity" :min="1"/><el-button @click="form.components.splice(i,1)">删除</el-button></div><el-button @click="form.components.push({sku:null,quantity:1})">添加现有 SKU</el-button></div></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">生成组合 SKU</el-button></template></el-dialog></section></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{useAuthStore}from'../../stores/auth';import{createBundleComponent,createProductSku,createProductSpu,fetchCodingOptions,fetchProductCategories,fetchProductColors,fetchProductMasterList,fetchProductSkuList}from'../../api/products';import{collectionRows,detailData}from'../../utils/businessResponse';const auth=useAuthStore(),canManage=computed(()=>auth.hasPermission('products.bundle.manage')),spus=ref([]),skus=ref([]),categories=ref([]),colors=ref([]),options=reactive({seasons:[]}),visible=ref(false),saving=ref(false),form=reactive({name:'',category:null,season:'5',color:null,components:[{sku:null,quantity:1}]});const bundles=computed(()=>spus.value.filter(x=>x.product_type==='bundle')),leaves=computed(()=>categories.value.filter(x=>x.level===3&&x.is_active)),normalSkus=computed(()=>{const ids=new Set(spus.value.filter(x=>x.product_type!=='bundle').map(x=>x.id));return skus.value.filter(x=>ids.has(x.spu))});async function load(){const[a,b,c,d,o]=await Promise.all([fetchProductMasterList({page_size:100}),fetchProductSkuList({page_size:100}),fetchProductCategories(),fetchProductColors(),fetchCodingOptions()]);spus.value=collectionRows(a.data);skus.value=collectionRows(b.data);categories.value=collectionRows(c.data);colors.value=collectionRows(d.data);Object.assign(options,detailData(o.data))}async function save(){if(!form.name||!form.category||!form.color||!form.components.length||form.components.some(x=>!x.sku))return ElMessage.warning('请完整填写组合商品及组成 SKU');saving.value=true;const p=await createProductSpu({product_name:form.name,category_node:form.category,season_code:form.season,product_type:'bundle'});if(!p.success){saving.value=false;return ElMessage.error(p.message)}const spu=detailData(p.data),category=categories.value.find(x=>x.id===form.category),spec_values=Object.fromEntries((category.spec_dimensions||[]).map(x=>[x.code,'组合']));const k=await createProductSku({spu:spu.id,color_code:form.color,spec_values});if(!k.success){saving.value=false;return ElMessage.error(k.message)}const sku=detailData(k.data);for(const x of form.components){const r=await createBundleComponent({bundle_sku:sku.id,component_sku:x.sku,quantity:x.quantity});if(!r.success){saving.value=false;return ElMessage.error(r.message)}}saving.value=false;visible.value=false;ElMessage.success(`组合 SKU ${sku.sku_code} 已生成`);load()}onMounted(load)</script>
<style scoped>.components{display:grid;gap:10px;width:100%}.components>div{display:grid;grid-template-columns:1fr 130px auto;gap:10px}</style>
